package org.jsoup.nodes;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.Collections;
import java.util.List;
import java.util.regex.Pattern;
import java.util.regex.PatternSyntaxException;
import org.jsoup.helper.StringUtil;
import org.jsoup.helper.Validate;
import org.jsoup.nodes.Element;
import org.jsoup.nodes.Tag;
import org.jsoup.nodes.TextNode;
import org.jsoup.parser.Parser;
import org.jsoup.parser.Tag;
import org.jsoup.parser.TagType;
import org.jsoup.select.Collector;
import org.jsoup.select.Elements;
import org.jsoup.select.Evaluator;
import org.jsoup.select.Selector;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

public class Element_previousElementSibling_TriageGen0Test {

    private Element parentElement;
    private Element firstChild;
    private Element secondChild;
    private Element thirdChild;

    @Before
    public void setUp() {
        parentElement = new Element(Tag.valueOf("div"), "");
        firstChild = new Element(Tag.valueOf("p"), "");
        secondChild = new Element(Tag.valueOf("span"), "");
        thirdChild = new Element(Tag.valueOf("a"), "");

        parentElement.appendChild(firstChild);
        parentElement.appendChild(secondChild);
        parentElement.appendChild(thirdChild);
    }

    @Test
    public void testPreviousElementSibling_FirstChild() {
        Element result = firstChild.previousElementSibling();
        assertNull(result);
    }

    @Test
    public void testPreviousElementSibling_SecondChild() {
        Element result = secondChild.previousElementSibling();
        assertEquals(firstChild, result);
    }

    @Test
    public void testPreviousElementSibling_ThirdChild() {
        Element result = thirdChild.previousElementSibling();
        assertEquals(secondChild, result);
    }

    @Test
    public void testPreviousElementSibling_NoParent() {
        Element orphan = new Element(Tag.valueOf("p"), "");
        Element result = orphan.previousElementSibling();
        assertNull(result);
    }

    @Test
    public void testPreviousElementSibling_SingleChild() {
        Element singleChild = new Element(Tag.valueOf("p"), "");
        parentElement.appendChild(singleChild);

        Element result = singleChild.previousElementSibling();
        assertNull(result);
    }

    @Test
    public void testPreviousElementSibling_EmptyList() {
        Element parent = new Element(Tag.valueOf("div"), "");
        Element result = parent.previousElementSibling();
        assertNull(result);
    }

    @Test
    public void testPreviousElementSibling_IndexIsNegative() {
        Element parent = new Element(Tag.valueOf("div"), "");
        Element result = parent.previousElementSibling();
        assertNull(result);
    }

    @Test
    public void testPreviousElementSibling_IndexOutOfBounds() {
        List<Element> siblings = Collections.singletonList(firstChild);
        Element mockElement = new Element(Tag.valueOf("p"), "") {
            @Override
            public List<Element> children() {
                return siblings;
            }

            @Override
            public Element parent() {
                return parentElement;
            }

            @Override
            public Integer indexInList() {
                return 1; // Out of bounds
            }
        };

        Element result = mockElement.previousElementSibling();
        assertNull(result);
    }
}
